console.log('=== 基础数据类型测试 ===');

// 基本类型
const test1 = {
    number: 123,
    string: 'hello',
    boolean: true,
    nullValue: null,
    undefined: undefined,
    symbol: Symbol('test')
};

const cloned1 = deepClone(test1);
console.log('原始:', test1);
console.log('克隆:', cloned1);
console.log('是否相等:', test1 === cloned1); // false
console.log('symbol 复制:', cloned1.symbol === test1.symbol); // true (Symbol 是基本类型)

